def split_csv(line):
    fields = []
    i = 0
    n = len(line)

    while i < n:
        # Check if field starts with a quote
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < n:
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < n and line[i + 1] == '"':
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: comma or end of line
                        if i < n and line[i] != ',':
                            return None
                        if i < n:
                            i += 1
                        fields.append(''.join(field))
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < n and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            if i < n:
                i += 1

    return fields

